import heapq

def match(orders):
    trades = []
    buy_heap = []   # (-price, idx, id) for resting buy orders
    sell_heap = []  # (price, idx, id) for resting sell orders
    book = {}       # id -> {'side', 'price', 'qty', 'idx', 'active'}
    counter = 0

    for order in orders:
        counter += 1
        idx = counter
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            if oid in book and book[oid]['active'] and book[oid]['qty'] > 0:
                book[oid]['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        remaining = qty

        if side == 'buy':
            heap = sell_heap
            while remaining > 0 and heap:
                p, hidx, hid = heap[0]
                o = book.get(hid)
                if o is None or not o['active'] or o['qty'] <= 0:
                    heapq.heappop(heap)
                    continue
                if price is not None and p > price:
                    break
                trade_qty = min(remaining, o['qty'])
                trades.append([oid, hid, p, trade_qty])
                remaining -= trade_qty
                o['qty'] -= trade_qty
                if o['qty'] == 0:
                    o['active'] = False
                    heapq.heappop(heap)
                if remaining == 0:
                    break
        else:  # sell
            heap = buy_heap
            while remaining > 0 and heap:
                negp, hidx, hid = heap[0]
                p = -negp
                o = book.get(hid)
                if o is None or not o['active'] or o['qty'] <= 0:
                    heapq.heappop(heap)
                    continue
                if price is not None and p < price:
                    break
                trade_qty = min(remaining, o['qty'])
                trades.append([hid, oid, p, trade_qty])
                remaining -= trade_qty
                o['qty'] -= trade_qty
                if o['qty'] == 0:
                    o['active'] = False
                    heapq.heappop(heap)
                if remaining == 0:
                    break

        if typ == 'limit' and remaining > 0:
            book[oid] = {'side': side, 'price': price, 'qty': remaining, 'idx': idx, 'active': True}
            if side == 'buy':
                heapq.heappush(buy_heap, (-price, idx, oid))
            else:
                heapq.heappush(sell_heap, (price, idx, oid))
        # ioc/market remainder is discarded (never rests)

    return trades

